const $=s=>document.querySelector(s), money=n=>'¥'+(n/100).toFixed(2), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photos={apple:'photo-1560806887-1e4cd0b6cbd6',rice:'photo-1586201375761-83865001e31c',orange:'photo-1547514701-42782101795e',avocado:'photo-1523049673857-eb18f1d7b578',oil:'photo-1474979266404-7eaacbcd87c5',nuts:'photo-1599599810769-bcde5a160d32',tea:'photo-1544787219-7f47ccb76574',honey:'photo-1587049352851-8d4e89133924',coffee:'photo-1447933601403-0c6688de566e',cup:'photo-1514228742587-6b1558fcca3d',towel:'photo-1600369671236-e74521d4b6ad',basket:'photo-1594224457860-23bdb45f8e3d'};
const photo=(k,w=700)=>`assets/${photos[k]?k:'apple'}.jpg`;
const gallery=p=>p.image==='apple'?[photo('apple'),'assets/apple-origin.jpg',photo('apple')]:[photo(p.image),photo(p.image),photo(p.image)];
function initial(){let defs=[['当季脆甜苹果','5斤装',5990,3800,0,'apple','山地日照 · 清脆多汁','山东 · 栖霞','时令鲜果'],['东北香米','5kg',6990,4500,1,'rice','一餐一饭，都是自然的香气','黑龙江 · 五常','粮油干货'],['赣南甜心脐橙','5斤装',4990,3200,0,'orange','果香充盈 · 酸甜恰好','江西 · 赣南','时令鲜果'],['熟度刚好牛油果','6枚装',5990,3900,0,'avocado','绵密细腻 · 轻食搭档','云南 · 孟连','时令鲜果'],['冷榨山茶油','500mL',8990,6200,1,'oil','一滴清香，点亮家常','浙江 · 衢州','粮油干货'],['原味混合坚果','500g',5990,3700,1,'nuts','每日一把 · 原味轻烘','浙江 · 杭州','粮油干货'],['清香高山绿茶','100g',7900,4800,1,'tea','山间清气，落入杯中','浙江 · 丽水','茶饮滋补'],['山野百花蜂蜜','500g',6900,4200,0,'honey','花香自然 · 温润日常','湖北 · 神农架','茶饮滋补'],['日晒精品咖啡豆','200g',8800,5500,1,'coffee','果香明亮 · 新鲜烘焙','云南 · 保山','茶饮滋补'],['日常白瓷马克杯','350mL',3900,2200,1,'cup','温润白瓷 · 好好喝水','福建 · 德化','日常好物'],['柔软纯棉毛巾','2条装',2990,1700,1,'towel','亲肤吸水 · 日常陪伴','河北 · 高阳','日常好物'],['自然编织收纳篮','中号',4900,2800,0,'basket','收纳有序 · 生活有度','山东 · 临沂','日常好物']];let products=defs.map((d,i)=>({id:i+1,name:d[0],specs:[{name:d[1],price:d[2],cost:d[3]},...(i===0?[{name:'10斤装',price:10990,cost:7200}]:i===1?[{name:'10kg',price:12990,cost:8500}]:[])],supplier:d[4],image:d[5],desc:d[6],origin:d[7],category:d[8],rate:10,active:true}));let s={products,cart:[],orders:[],settlements:[],ref:null,address:{name:'林悦（虚构）',phone:'13800000000',detail:'浙江省杭州市 · 好物演示社区 1号楼101室（虚构地址）'},seq:1000};function order(id,pid,status,days,refund){let p=products[pid-1],sp=p.specs[0];return{id,created:Date.now()-days*86400000,paid:status!=='待付款',ref:status==='已完成'?'HG001':null,address:{...s.address},items:[{uid:id+'-1',pid,name:p.name,spec:sp.name,price:sp.price,cost:sp.cost,rate:p.rate,qty:1,supplier:p.supplier,image:p.image,status,refund:refund||null,eligible:status==='已完成',commissionSettled:status==='已完成',supplySettled:status==='已完成',tracking:status==='已发货'||status==='已完成'?'DEMO202611'+id.slice(-4):'',events:status==='已发货'||status==='已完成'?[{text:'演示包裹已由供应商交付承运',time:Date.now()-86400000}]:[]}]}}s.settlements=[{id:'JS-HISTORY-C',type:'commission',amount:390,time:Date.now()-3*86400000},{id:'JS-HISTORY-S',type:'supply',supplier:1,amount:2200,time:Date.now()-3*86400000}];s.orders=[order('HG202611130901',3,'待付款',0),order('HG202611120802',5,'待发货',1),order('HG202611110703',7,'已发货',2),order('HG202611080604',10,'已完成',5),order('HG202611100505',6,'待发货',3,'pending')];return s}
let S;try{S=JSON.parse(localStorage.getItem('haowuji-v1'))||initial()}catch{S=initial()}let role='消费者',view='home',tab='',supplier=0,filter='',sort='default',query='',spec=0,qty=1,current=1,checkout=[],orderFilter='全部';const cats=['时令鲜果','粮油干货','茶饮滋补','日常好物'],suppliers=['青禾果园','谷仓食集'];
function save(){localStorage.setItem('haowuji-v1',JSON.stringify(S))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}function go(v){if(['home','list','detail','cart','checkout','success','orders'].includes(v)){role='消费者';tab=''}view=v;render();scrollTo(0,0)}function setRole(r){role=r;tab='';query='';filter='';orderFilter='全部';view=r==='消费者'?'home':r==='推广员'?'promoter':r==='供应商'?'supplier':'admin';render();scrollTo(0,0)}function modal(html){$('#modal').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="dialog">${html}<div style="text-align:right;margin-top:20px"><button onclick="closeModal()">关闭</button></div></div></div>`}function closeModal(){$('#modal').innerHTML=''}function confirmAction(title,body,fn){window.confirmFn=()=>{closeModal();fn()};modal(`<h2>${title}</h2><p style="line-height:1.9">${body}</p><button class="primary" onclick="confirmFn()">${title.startsWith('确认')?title:'确认'+title}</button>`)}
function image(k,cls='',w=700){return `<img class="${cls}" src="${photo(k,w)}" alt="${esc(k)} 商品实拍样例" onerror="this.onerror=null;this.src='fallback.svg'">`}
function toolbar(){return `<div class="toolbar"><span class="badge">演示环境</span>${['消费者','推广员','供应商','平台管理'].map(r=>`<button class="${role===r?'active':''}" onclick="setRole('${r}')">${r}</button>`).join('')}<span class="divider"></span><button onclick="guide()">演示指引</button><button onclick="loadCart()">载入购物车</button><button onclick="advance()">模拟满足结算条件</button><button onclick="reset()">重置</button></div>`}
function header(){return `<div class="topnote">好物不必远寻 · 让每一份日常，都有自然的滋味 <span class="badge">演示环境</span></div><header><div class="logo" onclick="go('home')" style="cursor:pointer">◒ 好物集<small>HAOWUJI · EVERYDAY GOODNESS</small></div><nav><a onclick="go('home')">首页</a><a onclick="filter='';go('list')">发现好物</a><a onclick="filter='时令鲜果';go('list')">时令鲜选</a><a onclick="go('home');setTimeout(()=>document.getElementById('story').scrollIntoView({behavior:'smooth'}),30)">产地故事</a></nav><div class="search"><input aria-label="搜索商品" placeholder="搜索一份好物" value="${esc(query)}" onkeydown="if(event.key==='Enter'){query=this.value;go('list')}"><button class="text" onclick="query=this.previousElementSibling.value;go('list')">⌕</button></div><button class="text" onclick="go('cart')">购物袋 <b>${S.cart.reduce((a,c)=>a+c.qty,0)}</b></button><button class="text" onclick="go('orders')">我的</button></header>`}
function card(p,promote=false){return `<article class="card"><div onclick="openProduct(${p.id})">${image(p.image)}<div style="position:absolute;top:14px;left:14px"><span class="tag">${esc(p.origin)}</span></div></div><div class="card-body"><span class="muted">${p.category} / ${suppliers[p.supplier]}</span><h3 onclick="openProduct(${p.id})" style="cursor:pointer">${esc(p.name)} <small>${esc(p.specs[0].name)}</small></h3><p class="muted">${esc(p.desc)}</p><div class="row"><span class="price">${money(p.specs[0].price)}</span><button class="${promote?'primary':'text'}" onclick="${promote?'share('+p.id+')':'add('+p.id+',0,1)'}">${promote?'分享赚 '+money(Math.round(p.specs[0].price*p.rate/100)):'＋ 加入'}</button></div></div></article>`}
function home(){return `${header()}<main class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">FROM THE ORIGIN, WITH CARE</div><h1>把产地的好，<br>带进日常。</h1><p>寻味山野，认真选物。<br>从一颗脆甜苹果，到一餐米饭的香气，<br>我们把朴素的好，带到你身边。</p><button class="primary" onclick="filter='';go('list')">逛逛好物 &nbsp; ↗</button><div class="muted" style="margin-top:30px;letter-spacing:2px">产地寻味 &nbsp; / &nbsp; 用心甄选 &nbsp; / &nbsp; 一件代发</div></div><div class="hero-image" style="background-image:url('${photo('apple',1300)}')"></div></section><div class="section-title"><div><h2>此刻，正当时。</h2><span class="muted">跟随时令，尝一口新鲜的自然。</span></div><button class="text" onclick="filter='时令鲜果';go('list')">时令精选 &nbsp; →</button></div><div class="grid">${S.products.filter(p=>p.active).slice(0,4).map(p=>card(p)).join('')}</div><div class="categories">${cats.map((c,i)=>`<div class="category" onclick="filter='${c}';go('list')"><div><strong>${c}</strong><p class="muted">${['把新鲜装进生活','一餐一饭的踏实','给日常一点滋养','让生活自然有序'][i]}</p></div><span>↗</span></div>`).join('')}</div><section id="story" class="story"><img src="assets/apple-origin.jpg" alt="枝头苹果 · 产地故事示意"><div><div class="eyebrow">MEET THE ORIGIN / 产地故事</div><h2>好味道，<br>从一片用心的土地开始。</h2><p>在这个虚构故事中，青禾果园沿着山坡而生。我们想分享的，是果实成熟时的清甜，也是等待一季的耐心。</p><button class="text" onclick="story()">走近青禾果园 &nbsp; →</button><div class="muted">供应商与故事均为虚构演示样例</div></div></section><div class="section-title"><div><h2>日常好物，常常惦记。</h2><span class="muted">认真生活的人，总有自己的回购清单。</span></div><button class="text" onclick="filter='';go('list')">发现更多 &nbsp; →</button></div><div class="grid">${S.products.filter(p=>p.active).slice(4,8).map(p=>card(p)).join('')}</div><div class="services"><span>◎ 平台精选好物</span><span>♧ 供应商产地直发</span><span>◇ 售后协作保障</span><span>♡ 每一份日常，用心对待</span></div></main><footer><div class="row"><div class="logo">好物集<small>把产地的好，带进日常。</small></div><div class="muted">品牌与商品交易均为演示样例<br><br>模拟支付 · 模拟物流 · 模拟结算</div></div></footer>`}
function story(){modal(`<span class="eyebrow">ORIGIN STORY</span><h2>青禾果园 · 等一颗苹果自然成熟</h2>${image('apple')}<p style="line-height:2">在虚构的青禾果园，我们用一个朴素的故事展示平台如何连接产地与日常。果园负责打包发货，平台负责选品、销售与售后协作，让一份新鲜有序抵达。</p><p class="muted">故事、人物与供应商均为演示，不代表真实认证或合作背书。</p>`)}
function list(){let ps=S.products.filter(p=>p.active&&(!filter||p.category===filter)&&(!query||(p.name+p.desc+p.origin).includes(query)));ps.sort((a,b)=>sort==='asc'?a.specs[0].price-b.specs[0].price:sort==='desc'?b.specs[0].price-a.specs[0].price:a.id-b.id);return `${header()}<main class="wrap page"><div class="section-title"><div><div class="eyebrow">THE GOOD THINGS</div><h2 style="margin-top:12px">发现，生活的好。</h2></div><span class="muted">共 ${ps.length} 件精选好物</span></div><div class="filters">${['全部',...cats].map(c=>`<button class="${filter===(c==='全部'?'':c)?'selected':''}" onclick="filter='${c==='全部'?'':c}';render()">${c}</button>`).join('')}<select aria-label="价格排序" onchange="sort=this.value;render()"><option value="default">推荐排序</option><option value="asc" ${sort==='asc'?'selected':''}>价格从低到高</option><option value="desc" ${sort==='desc'?'selected':''}>价格从高到低</option></select>${query?`<button onclick="query='';render()">清除搜索：${esc(query)} ×</button>`:''}</div><div class="grid">${ps.map(p=>card(p)).join('')}</div>${!ps.length?'<div class="empty">没有找到相关好物，换个关键词试试。</div>':''}</main>`}
function openProduct(id){current=id;spec=0;qty=1;go('detail')}
function detail(){let p=S.products.find(x=>x.id===current)||S.products[0],sp=p.specs[spec]||p.specs[0];return `${header()}<main class="wrap page"><p class="muted"><a onclick="go('home')">首页</a> / <a onclick="go('list')">${p.category}</a> / ${esc(p.name)}</p><div class="detail"><div><div style="overflow:hidden;border-radius:8px;background:#eaece2">${image(p.image)}</div><div class="inline" style="margin-top:12px">${gallery(p).map((src,i)=>`<button style="padding:0;width:75px;overflow:hidden" onclick="document.querySelector('.detail img').src='${src}';document.querySelector('.detail img').style.objectFit='${i===1&&p.image!=='apple'?'contain':'cover'}';document.querySelector('.detail img').style.objectPosition='${i===2?'right bottom':'center'}';document.querySelector('.detail img').style.transform='${i===2?'scale(1.2)':'none'}';toast('${['整体展示','原图展示','细节放大'][i]}')"><img src="${src}" alt="${esc(p.name)} ${['整体','原图','细节'][i]}" onerror="this.src='fallback.svg'"></button>`).join('')}<span class="muted">商品摄影为演示样例 · 支持切换细节</span></div></div><div><span class="tag">产地精选 · ${p.origin}</span><h1>${esc(p.name)} ${esc(sp.name)}</h1><p style="color:#7c8677">${esc(p.desc)}</p><div class="panel" style="background:#efeee5;border:0"><span class="muted">好物价</span><div class="price" style="font-size:36px;margin:12px 0">${money(sp.price)}</div><span class="muted">产地直发 · 本演示全场免运费</span></div><p>选择规格</p><div class="specs">${p.specs.map((s,i)=>`<button class="${i===spec?'selected':''}" onclick="spec=${i};render()">${esc(s.name)}</button>`).join('')}</div><div class="inline">数量 <button onclick="qty=Math.max(1,qty-1);render()">−</button><strong>${qty}</strong><button onclick="qty=Math.min(99,qty+1);render()">＋</button></div><div class="product-note">发货供应商：${suppliers[p.supplier]}<br>产地：${p.origin}<br>发货说明：演示订单支付后，由供应商独立发货。<br>售后说明：支持商品项售后申请，由平台审核模拟退款。</div><div class="inline"><button class="primary" onclick="add(${p.id},${spec},qty)">加入购物车</button><button class="buy" onclick="buyNow(${p.id},${spec},qty)">立即购买</button><button onclick="share(${p.id})">分享 ↗</button></div>${S.ref?'<p class="muted">本次选购由推广员「陈沐」分享（HG001）</p>':''}</div></div><div class="panel" style="margin-top:35px"><h2>把简单的好，带到每一天。</h2><p style="line-height:2">${esc(p.desc)}。规格 ${esc(sp.name)}，由${suppliers[p.supplier]}提供履约服务。商品、产地信息、价格及图片仅用于业务演示。</p></div></main>`}
function add(pid,si=0,n=1){let p=S.products.find(x=>x.id===pid);if(!p||!p.active)return toast('商品已下架');let c=S.cart.find(x=>x.pid===pid&&x.si===si);if(c)c.qty=Math.min(99,c.qty+n);else S.cart.push({pid,si,qty:n,selected:true});save();render();toast('已加入购物车')}
function cartRows(items,edit=false){return items.map((c,i)=>{let p=S.products.find(p=>p.id===c.pid),sp=p.specs[c.si];return `<div class="lineitem">${edit?`<input type="checkbox" ${c.selected?'checked':''} onchange="S.cart[${i}].selected=this.checked;save();render()">`:''}${image(p.image)}<div class="info"><h3>${esc(p.name)}</h3><div class="muted">${sp.name} · ${suppliers[p.supplier]}</div></div><span>${money(sp.price)}</span>${edit?`<input aria-label="商品数量" type="number" min="1" max="99" value="${c.qty}" onchange="S.cart[${i}].qty=Math.max(1,Math.min(99,Number(this.value)||1));save();render()"><button class="text" onclick="S.cart.splice(${i},1);save();render()">删除</button>`:`<span>× ${c.qty}</span>`}</div>`}).join('')}
function cartTotal(items){return items.reduce((a,c)=>a+S.products.find(p=>p.id===c.pid).specs[c.si].price*c.qty,0)}
function cart(){let chosen=S.cart.filter(c=>c.selected);return `${header()}<main class="wrap page"><div class="section-title"><div><h2>我的购物袋</h2><span class="muted">把喜欢的好物，一起带回家。</span></div><button onclick="loadCart()">一键载入两款核心演示商品</button></div><div class="panel">${cartRows(S.cart,true)||'<div class="empty">购物袋还是空的。<br><br><button onclick="go(\'list\')">去发现好物</button></div>'}</div><div class="panel row"><label><input type="checkbox" ${S.cart.length&&S.cart.every(c=>c.selected)?'checked':''} onchange="S.cart.forEach(c=>c.selected=this.checked);save();render()"> 全选</label><div class="inline">已选 ${chosen.length} 件 <span class="price">${money(cartTotal(chosen))}</span><button class="buy" onclick="startCheckout()">去结算 →</button></div></div>${S.ref?'<p class="muted">推广归属：陈沐 HG001 · 消费者：林悦，两人为不同虚构人物。</p>':''}</main>`}
function loadCart(){S.ref='HG001';S.cart=[{pid:1,si:0,qty:1,selected:true},{pid:2,si:0,qty:1,selected:true}];save();role='消费者';go('cart');toast('已载入 ¥129.80 购物车，并关联推广员陈沐')}
function startCheckout(){checkout=S.cart.filter(c=>c.selected).map(c=>({...c}));if(!checkout.length)return toast('请先勾选商品');if(checkout.some(c=>!S.products.find(p=>p.id===c.pid)?.active))return toast('有商品已下架，请移出购物车');go('checkout')}
function buyNow(pid,si,n){if(!S.products.find(p=>p.id===pid)?.active)return toast('商品已下架');checkout=[{pid,si,qty:n}];go('checkout')}
function editAddress(){modal(`<h2>编辑演示收货信息</h2><p class="muted">请仅使用虚构信息。</p><label>收货人<input id="an" value="${esc(S.address.name)}"></label><label>演示电话<input id="ap" value="${esc(S.address.phone)}"></label><label>演示地址<input id="ad" value="${esc(S.address.detail)}"></label><button class="primary" onclick="saveAddress()">保存地址</button>`)}function saveAddress(){let name=$('#an').value.trim(),phone=$('#ap').value.trim(),detail=$('#ad').value.trim();if(!name||!phone||!detail)return toast('请补全演示地址');S.address={name,phone,detail};save();closeModal();render()}
function checkoutPage(){return `${header()}<main class="wrap page"><h1>确认订单</h1><div class="panel row"><div><h3>收货信息 · 虚构演示</h3><p>${esc(S.address.name)} &nbsp; ${esc(S.address.phone)}</p><p>${esc(S.address.detail)}</p></div><button onclick="editAddress()">编辑</button></div>${suppliers.map((s,i)=>{let cs=checkout.filter(c=>S.products.find(p=>p.id===c.pid).supplier===i);return cs.length?`<div class="panel"><span class="tag">由 ${s} 发货</span>${cartRows(cs)}<p style="text-align:right" class="muted">免运费 · 供应商独立履约</p></div>`:''}).join('')}<div class="panel row"><div class="muted">${S.ref?'推广员：陈沐 HG001':'未关联推广员'}<br><br>模拟支付，不发生真实扣款</div><div class="inline"><span class="price">${money(cartTotal(checkout))}</span><button id="paybtn" class="buy" onclick="pay()">模拟支付</button></div></div></main>`}
function pay(){if(checkout.some(c=>!S.products.find(p=>p.id===c.pid)?.active))return toast('商品已下架，请重新选购');if(!checkout.length)return toast('没有待结算商品');let items=checkout.map((c,i)=>{let p=S.products.find(p=>p.id===c.pid),sp=p.specs[c.si];return{uid:'L'+Date.now()+i,pid:p.id,name:p.name,spec:sp.name,price:sp.price,cost:sp.cost,rate:p.rate,qty:c.qty,supplier:p.supplier,image:p.image,status:'待发货',refund:null,eligible:false,commissionSettled:false,supplySettled:false,tracking:'',events:[]}});let id='HG'+new Date().toISOString().slice(0,10).replaceAll('-','')+(++S.seq);S.orders.unshift({id,created:Date.now(),paid:true,ref:S.ref,address:{...S.address},items});S.cart=S.cart.filter(c=>!checkout.some(x=>x.pid===c.pid&&x.si===c.si));checkout=[];current=id;save();go('success')}
function success(){let o=S.orders.find(o=>o.id===current);return `${header()}<main class="wrap page success"><div class="check">✓</div><h1>模拟支付成功</h1><p>一份好物，正在奔向你的日常。</p><p class="muted">订单 ${o.id} · ${new Set(o.items.map(i=>i.supplier)).size} 个供应商履约子单</p><p class="price">${money(total(o))}</p><button class="primary" onclick="go('orders')">查看订单</button> <button onclick="setRole('推广员')">查看推广佣金</button></main>`}
const total=o=>o.items.reduce((a,i)=>a+i.price*i.qty,0),allItems=()=>S.orders.filter(o=>o.paid).flatMap(o=>o.items.map(i=>({...i,order:o}))), commission=i=>Math.round(i.price*i.qty*i.rate/100),supply=i=>i.cost*i.qty;
const state=i=>i.refund==='pending'?'售后中':i.refund==='approved'?'已退款':i.status;
function orderStatus(o){if(!o.paid)return '待付款';if(o.items.every(i=>i.refund==='approved'))return '已退款';if(o.items.some(i=>i.refund==='pending'))return '售后中';let live=o.items.filter(i=>i.refund!=='approved');return live.every(i=>i.status==='已完成')?'已完成':live.some(i=>i.status==='已发货')?'已发货':'待发货'}
function itemButtons(o,i){if(!o.paid)return'';return `${i.refund==='approved'?'<span class="muted">该商品已退款，子单已取消</span>':i.refund==='pending'?'<span class="muted">待平台审批 · 对应佣金与应付已冻结</span>':`<button onclick="requestRefund('${o.id}','${i.uid}')">申请退款</button>${i.status==='已发货'?`<button class="primary" onclick="receive('${o.id}','${i.uid}')">确认收货</button>`:''}`}${i.tracking?`<button onclick="logistics('${o.id}','${i.uid}')">包裹信息</button>`:''}`}
function orders(){let os=S.orders.filter(o=>orderFilter==='全部'||orderStatus(o)===orderFilter);return `${header()}<main class="wrap page"><h1>我的订单</h1><p class="muted">林悦 · 虚构消费者 | 按商品独立履约与售后</p><div class="filters">${['全部','待付款','待发货','已发货','已完成','售后中','已退款'].map(s=>`<button class="${orderFilter===s?'selected':''}" onclick="orderFilter='${s}';render()">${s}</button>`).join('')}</div>${os.map(o=>`<div class="panel"><div class="row"><div><b>${o.id}</b> <span class="muted">${new Date(o.created).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}</span></div><span class="status">${orderStatus(o)}</span></div>${o.items.map(i=>`<div class="lineitem">${image(i.image)}<div class="info"><h3>${esc(i.name)} ${esc(i.spec)}</h3><p class="muted">${suppliers[i.supplier]} · 子单 ${o.id}-${i.supplier+1}</p><span class="status">${state(i)}</span></div><div style="text-align:right">${money(i.price*i.qty)} <span class="muted">×${i.qty}</span><div class="filters">${itemButtons(o,i)}</div></div></div>`).join('')}<div class="row" style="margin-top:18px"><button onclick="orderDetail('${o.id}')">订单详情</button><div>订单总额 <b>${money(total(o))}</b> ${!o.paid?`<button class="buy" onclick="payExisting('${o.id}')">模拟支付</button>`:''}</div></div></div>`).join('')||'<div class="empty">暂无此状态订单</div>'}</main>`}
function findItem(oid,uid){let o=S.orders.find(o=>o.id===oid);return[o,o.items.find(i=>i.uid===uid)]}
function payExisting(id){let o=S.orders.find(o=>o.id===id);if(o.paid)return;o.paid=true;o.items.forEach(i=>i.status='待发货');save();render();toast('模拟支付成功，已生成待发货任务')}
function requestRefund(oid,uid){let[o,i]=findItem(oid,uid);if(i.refund)return;modal(`<h2>申请商品项退款</h2><p>${esc(i.name)} ${esc(i.spec)}</p><p class="price">${money(i.price*i.qty)}</p><label>演示原因<select id="reason"><option>暂时不需要了（演示）</option><option>商品问题（演示）</option></select></label><p class="muted">仅影响此商品项。审核期间，对应待结算佣金与供货应付冻结。已结算项目由平台记录冲抵，不产生真实资金流。</p><button class="buy" onclick="submitRefund('${oid}','${uid}')">提交退款申请</button>`)}
function submitRefund(oid,uid){let[o,i]=findItem(oid,uid);if(i.refund)return;i.refund='pending';i.reason=$('#reason').value;i.preRefundStatus=i.status;save();closeModal();render();toast('售后申请已提交，待结算金额已冻结')}
function receive(oid,uid){confirmAction('确认收货','仅确认该供应商商品项，结算仍需演示工具推进等待期。',()=>{let[o,i]=findItem(oid,uid);if(i.refund||i.status!=='已发货')return;i.status='已完成';i.events.push({text:'消费者已确认收货（演示）',time:Date.now()});save();render();toast('已确认收货，等待满足结算条件')})}
function logistics(oid,uid){let[o,i]=findItem(oid,uid);modal(`<h2>演示包裹信息</h2><span class="badge">模拟物流 · 非真实轨迹</span><p>${suppliers[i.supplier]} · 演示快递</p><h3>${esc(i.tracking)}</h3>${i.events.map(e=>`<div class="panel">● ${esc(e.text)}<p class="muted">${new Date(e.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</p></div>`).join('')}`)}
function orderDetail(id){let o=S.orders.find(o=>o.id===id),hide=role==='推广员';modal(`<h2>订单详情</h2><p>${o.id} · ${orderStatus(o)}</p>${hide?'<p class="muted">消费者：林** · 推广视图已隐藏收货信息</p>':`<p>${esc(o.address.name)} · ${esc(o.address.phone)}<br>${esc(o.address.detail)}</p>`}${o.items.filter(i=>role!=='供应商'||i.supplier===supplier).map(i=>`<div class="panel"><b>${esc(i.name)} ${esc(i.spec)}</b><p>${money(i.price*i.qty)} · ${state(i)}</p><p class="muted">供应商 ${suppliers[i.supplier]} · 商品项独立履约</p>${!hide?`<p class="muted">单价快照 ${money(i.price)} / 供货价 ${money(i.cost)} / 佣金比例 ${i.rate}%</p>`:''}</div>`).join('')}<p>${role==='供应商'?'本供应商子单金额':'订单总额'} ${money(role==='供应商'?o.items.filter(i=>i.supplier===supplier).reduce((a,i)=>a+i.price*i.qty,0):total(o))}</p>`)}
function share(pid){let link=location.origin+location.pathname+'?product='+pid+'&ref=HG001';modal(`<h2>分享一份好物</h2><p>${esc(S.products.find(p=>p.id===pid).name)}</p><span class="tag">推广员：陈沐 · HG001</span><label>专属站内链接<input id="sharelink" readonly value="${esc(link)}"></label><button class="primary" onclick="copyShare()">复制专属链接</button> <button onclick="closeModal();S.ref='HG001';save();role='消费者';openProduct(${pid});toast('已通过陈沐的推广入口进入')">以消费者身份打开</button><p class="muted">只计算本人直接促成的成交；同一浏览器本地演示归属。外部访客拥有独立演示数据。</p>`)}
async function copyShare(){let el=$('#sharelink');try{await navigator.clipboard.writeText(el.value);toast('专属链接已复制')}catch{el.select();document.execCommand('copy');toast('链接已复制')}}
function sums(items,type){let fn=type==='commission'?commission:supply,flag=type==='commission'?'commissionSettled':'supplySettled',valid=items.filter(i=>i.refund!=='approved');return{estimated:valid.filter(i=>!i[flag]&&i.refund!=='pending'&&!i.eligible).reduce((a,i)=>a+fn(i),0),frozen:valid.filter(i=>i.refund==='pending'&&!i[flag]).reduce((a,i)=>a+fn(i),0),ready:valid.filter(i=>i.refund!=='pending'&&i.eligible&&!i[flag]).reduce((a,i)=>a+fn(i),0),settled:valid.filter(i=>i[flag]).reduce((a,i)=>a+fn(i),0)}}
function statsBox(arr){return `<div class="stats">${arr.map(([l,v])=>`<div class="stat"><span class="muted">${l}</span><strong>${v}</strong></div>`).join('')}</div>`}
function promoter(){let items=allItems().filter(i=>i.order.ref==='HG001'),m=sums(items,'commission');return `${header()}<main class="wrap page"><div class="row"><div><span class="eyebrow">MY CREATOR STUDIO</span><h1>你好，陈沐。</h1><p class="muted">分享你喜欢的好物，让好生活发生。 · HG001 · 虚构推广员</p></div><button class="primary" onclick="S.ref='HG001';save();role='消费者';go('home');toast('已关联陈沐的推广入口')">进入我的推广商城 ↗</button></div>${statsBox([['直接推广有效成交额',money(items.filter(i=>i.refund!=='approved').reduce((a,i)=>a+i.price*i.qty,0))],['预估佣金',money(m.estimated)],['售后冻结',money(m.frozen)],['可结算佣金',money(m.ready)]])}<div class="panel row"><div>演示已结算 <b>${money(m.settled)}</b><p class="muted">仅本人直接促成订单 · 无层级、无间接佣金</p></div><button onclick="settle('commission')" class="primary">模拟结算佣金</button></div><div class="filters">${['可推广商品','推广订单与佣金','结算记录'].map(t=>`<button class="${(tab||'可推广商品')===t?'selected':''}" onclick="tab='${t}';render()">${t}</button>`).join('')}</div>${!tab||tab==='可推广商品'?`<div class="grid">${S.products.filter(p=>p.active).map(p=>card(p,true)).join('')}</div>`:tab==='结算记录'?records('commission'):commissionTable(items)}</main>`}
function commissionState(i){return i.refund==='approved'?'已冲减':i.commissionSettled?'演示已结算':i.refund==='pending'?'售后冻结':i.eligible?'可结算':'预估'}
function commissionTable(items){return table(['订单 / 商品','成交金额','比例','佣金','状态','操作'],items.map(i=>[`<b>${i.order.id}</b><p class="muted">${esc(i.name)} · ${esc(i.spec)}</p>`,money(i.price*i.qty),i.rate+'%',money(commission(i)),`<span class="status">${commissionState(i)}</span>`,`<button onclick="orderDetail('${i.order.id}')">详情</button>`]))}
function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${head.length}" class="empty">暂无记录</td></tr>`}</tbody></table></div>`}
function shell(type,content){let isSup=type==='supplier',tabs=isSup?['履约订单','供货商品','应收与结算']:['经营概览','商品管理','订单管理','售后处理','推广管理','供应商与结算'];return `<div class="admin"><aside class="sidebar"><div class="logo" style="font-size:24px">◒ 好物集</div><p class="muted">${isSup?'供应商工作台':'平台管理中心'}</p>${tabs.map(t=>`<button class="${(tab||tabs[0])===t?'selected':''}" onclick="tab='${t}';query='';render()">${t}</button>`).join('')}<p class="muted">演示角色切换<br>不代表生产权限系统</p></aside><main class="adminmain"><div class="row"><span class="muted">好物集 / ${isSup?'供应商协作':'管理工作台'} / ${tab||tabs[0]}</span><span class="badge">演示环境 · 本地共享状态</span></div>${content}</main></div>`}
function supplierPage(){let items=allItems().filter(i=>i.supplier===supplier),m=sums(items,'supply');let title=`<div class="row"><div><h1>${suppliers[supplier]}</h1><p class="muted">虚构供应商 · 仅展示自己的履约商品项</p></div><select aria-label="切换供应商" onchange="supplier=Number(this.value);render()">${suppliers.map((s,i)=>`<option value="${i}" ${supplier===i?'selected':''}>${s}</option>`).join('')}</select></div>`;let content=title+statsBox([['待发货',items.filter(i=>i.status==='待发货'&&!i.refund).length],['已发货',items.filter(i=>i.status==='已发货'&&!i.refund).length],['售后中',items.filter(i=>i.refund==='pending').length],['可结算金额',money(m.ready)]]);if(tab==='供货商品')content+=table(['商品','规格','供货价','零售价','状态'],S.products.filter(p=>p.supplier===supplier).flatMap(p=>p.specs.map(sp=>[esc(p.name),esc(sp.name),money(sp.cost),money(sp.price),p.active?'在售':'已下架'])));else if(tab==='应收与结算')content+=supplyPanel(items,m);else content+=`<div class="filters"><input placeholder="搜索订单或商品" value="${esc(query)}" oninput="query=this.value;renderKeepFocus(this)"><select onchange="orderFilter=this.value;render()">${['全部','待发货','已发货','已完成','售后中','已退款'].map(s=>`<option ${orderFilter===s?'selected':''}>${s}</option>`).join('')}</select></div>`+fulfillTable(items.filter(i=>(orderFilter==='全部'||state(i)===orderFilter)&&(!query||(i.order.id+i.name).includes(query))));return shell('supplier',content)}
function renderKeepFocus(el){let pos=el.selectionStart;render();let input=document.querySelector('.filters input');if(input){input.focus();input.setSelectionRange(pos,pos)}}
function fulfillTable(items){return table(['履约子单 / 商品','金额 / 供货应付','状态','物流 / 售后','操作'],items.map(i=>[`<b>${i.order.id}-${i.supplier+1}</b><p>${esc(i.name)} × ${i.qty}</p><span class="muted">${suppliers[i.supplier]}</span>`,`${money(i.price*i.qty)}<p class="muted">供货 ${money(supply(i))}</p>`,`<span class="status">${state(i)}</span>`,i.refund==='pending'?`<span class="muted">${esc(i.reason||'演示售后申请')}<br>待平台协作审核</span>`:esc(i.tracking||'尚未发货'),`<button onclick="orderDetail('${i.order.id}')">详情</button> ${i.status==='待发货'&&!i.refund?`<button class="primary" onclick="shipDialog('${i.order.id}','${i.uid}')">发货</button>`:''}`]))}
function shipDialog(oid,uid){modal(`<h2>供应商发货</h2><span class="badge">演示物流</span><label>承运商<input value="演示快递" readonly></label><label>模拟物流单号<input id="tracking" value="DEMO${Date.now()}"></label><button class="primary" onclick="ship('${oid}','${uid}')">确认模拟发货</button>`)}
function ship(oid,uid){let track=$('#tracking').value.trim();if(!track)return toast('请录入演示物流单号');let[o,i]=findItem(oid,uid);if(i.status!=='待发货'||i.refund)return toast('当前商品项不能发货');i.status='已发货';i.tracking=track;i.events.push({text:'供应商已发货，包裹已揽收（演示）',time:Date.now()});save();closeModal();render();toast('已发货，消费者与平台已同步')}
function supplyPanel(items,m){return statsBox([['预计应收',money(m.estimated)],['售后冻结',money(m.frozen)],['可结算',money(m.ready)],['演示已结算',money(m.settled)]])+`<p><button class="primary" onclick="settle('supply',${supplier})">模拟结算供应商应付</button></p>`+table(['订单 / 商品','供货应付','状态'],items.map(i=>[i.order.id+'<p class="muted">'+esc(i.name)+'</p>',money(supply(i)),i.refund==='approved'?'已冲减':i.supplySettled?'演示已结算':i.refund==='pending'?'售后冻结':i.eligible?'可结算':'预计应收']))+`<h3>结算记录</h3>`+records('supply',supplier)}
function records(type,sup){return table(['记录号','结算对象','金额','时间','结果'],S.settlements.filter(r=>r.type===type&&(sup===undefined||r.supplier===sup)).map(r=>[r.id,r.type==='commission'?'陈沐 HG001':suppliers[r.supplier],money(r.amount),new Date(r.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),r.note||'模拟结算完成']))}
function settle(type,sup){let flag=type==='commission'?'commissionSettled':'supplySettled',items=allItems().filter(i=>i.eligible&&!i.refund&&!i[flag]&&(type==='commission'?i.order.ref==='HG001':i.supplier===sup)),amount=items.reduce((a,i)=>a+(type==='commission'?commission(i):supply(i)),0);if(!amount)return toast('暂无可结算金额，请确认收货并模拟满足结算条件');confirmAction('模拟结算',`${type==='commission'?'陈沐的直接推广佣金':suppliers[sup]+'供货应付'}：${money(amount)}。确认后生成演示记录，不发生真实转账。`,()=>{let actual=0;items.forEach(x=>{let[o,i]=findItem(x.order.id,x.uid);if(i.eligible&&!i.refund&&!i[flag]){i[flag]=true;actual+=type==='commission'?commission(i):supply(i)}});if(actual)S.settlements.unshift({id:'JS'+Date.now(),type,supplier:sup,amount:actual,time:Date.now(),itemIds:items.map(i=>i.uid)});save();render();toast('模拟结算完成，记录已保存')})}
function advance(){confirmAction('推进结算等待期','演示操作：将所有已确认收货且无待处理售后的商品项推进为可结算，不会替未发货或未收货商品确认收货。',()=>{let n=0;S.orders.filter(o=>o.paid).forEach(o=>o.items.forEach(i=>{if(i.status==='已完成'&&!i.refund&&!i.eligible){i.eligible=true;n++}}));save();render();toast(`已推进 ${n} 个商品项的结算等待期`)})}
function adminPage(){let t=tab||'经营概览',items=allItems(),content=`<div class="row"><h1>${t}</h1><span class="muted">${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})} · 数据随演示操作更新</span></div>`;if(t==='经营概览'){let sales=items.reduce((a,i)=>a+i.price*i.qty,0),refunds=items.filter(i=>i.refund==='approved').reduce((a,i)=>a+i.price*i.qty,0);content+=statsBox([['累计支付销售额',money(sales)],['模拟退款额',money(refunds)],['有效销售额',money(sales-refunds)],['已支付订单',S.orders.filter(o=>o.paid).length],['待发货子单',subCount(items.filter(i=>i.status==='待发货'&&!i.refund))],['售后商品项',items.filter(i=>i.refund==='pending').length],['有效推广佣金',money(items.filter(i=>i.order.ref&&!['approved'].includes(i.refund)).reduce((a,i)=>a+commission(i),0))],['供货应付净额',money(items.filter(i=>i.refund!=='approved').reduce((a,i)=>a+supply(i),0))]]);let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return{label:(d.getMonth()+1)+'/'+d.getDate(),key:d.toDateString()}}),vs=days.map(d=>S.orders.filter(o=>o.paid&&new Date(o.created).toDateString()===d.key).reduce((a,o)=>a+total(o),0)),max=Math.max(...vs,1);let ranks=S.products.map(p=>({p,value:items.filter(i=>i.pid===p.id&&i.refund!=='approved').reduce((a,i)=>a+i.price*i.qty,0)})).sort((a,b)=>b.value-a.value).slice(0,5);content+=`<div class="two"><div class="panel"><h3>近七日支付销售趋势</h3><p class="muted">支付口径 · 退款独立统计</p><div class="chart">${vs.map((v,i)=>`<div class="bar" style="height:${Math.max(3,v/max*100)}%" title="${days[i].label} ${money(v)}"><span>${days[i].label}</span></div>`).join('')}</div></div><div class="panel"><h3>商品有效销售排行</h3>${ranks.map((r,i)=>`<div class="row" style="padding:12px 0;border-bottom:1px solid var(--line)"><span><span class="muted">0${i+1}</span> &nbsp; ${esc(r.p.name)}</span><b>${money(r.value)}</b></div>`).join('')}</div></div>`}else if(t==='商品管理'){let ps=S.products.filter(p=>(!query||p.name.includes(query))&&(!filter||p.category===filter));content+=`<div class="filters"><input placeholder="搜索商品名称" value="${esc(query)}" oninput="query=this.value;renderKeepFocus(this)"><select onchange="filter=this.value;render()"><option value="">全部分类</option>${cats.map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select><button class="primary" onclick="editProduct()">＋ 新增商品</button></div>`+table(['商品','分类 / 供应商','零售价','供货价','佣金','状态','操作'],ps.map(p=>[`<div class="inline">${image(p.image,'miniimg',150)}${esc(p.name)}</div>`,p.category+'<p class="muted">'+suppliers[p.supplier]+'</p>',money(p.specs[0].price),money(p.specs[0].cost),p.rate+'%',p.active?'在售':'已下架',`<button onclick="editProduct(${p.id})">编辑</button> <button onclick="toggleProduct(${p.id})">${p.active?'下架':'上架'}</button>`]))}else if(t==='订单管理'){let os=S.orders.filter(o=>(!query||o.id.includes(query))&&(orderFilter==='全部'||orderStatus(o)===orderFilter));content+=`<div class="filters"><input placeholder="搜索主订单号" value="${esc(query)}" oninput="query=this.value;renderKeepFocus(this)"><select onchange="orderFilter=this.value;render()">${['全部','待付款','待发货','已发货','已完成','售后中','已退款'].map(s=>`<option ${s===orderFilter?'selected':''}>${s}</option>`).join('')}</select></div>`+table(['主订单','金额','支付','履约子单','售后 / 状态','操作'],os.map(o=>[o.id,money(total(o)),o.paid?'已模拟支付':'待付款',[...new Set(o.items.map(i=>i.supplier))].map(s=>suppliers[s]+' · '+o.items.filter(i=>i.supplier===s).map(state).join(' / ')).join('<br>'),orderStatus(o),`<button onclick="orderDetail('${o.id}')">详情</button>`]))}else if(t==='售后处理'){content+=`<p class="muted">退款以商品项处理。申请中冻结，完成后冲减，其他供应商履约继续。</p>`+table(['订单 / 商品','退款金额','关联佣金 / 供货应付','原因','状态','操作'],items.filter(i=>i.refund).map(i=>[i.order.id+'<p>'+esc(i.name)+'</p>',money(i.price*i.qty),money(i.order.ref?commission(i):0)+' / '+money(supply(i)),esc(i.reason||'暂时不需要了（演示）'),state(i),i.refund==='pending'?`<button class="buy" onclick="approve('${i.order.id}','${i.uid}')">审批并模拟退款</button> <button onclick="reject('${i.order.id}','${i.uid}')">驳回</button>`:'退款已完成']))}else if(t==='推广管理'){let its=items.filter(i=>i.order.ref==='HG001'),m=sums(its,'commission');content+=`<div class="panel row"><div><h3>陈沐 · HG001</h3><span class="muted">虚构推广员 · 仅直接推广</span></div><button class="primary" onclick="settle('commission')">模拟结算</button></div>`+statsBox([['预估佣金',money(m.estimated)],['冻结',money(m.frozen)],['可结算',money(m.ready)],['演示已结算',money(m.settled)]])+commissionTable(its)+`<h3>结算记录</h3>`+records('commission')}else{content+=`<div class="filters">${suppliers.map((s,i)=>`<button class="${supplier===i?'selected':''}" onclick="supplier=${i};render()">${s}</button>`).join('')}</div><p class="muted">${suppliers[supplier]} · 虚构供应商 · ${S.products.filter(p=>p.supplier===supplier).length} 款供货商品</p>`+supplyPanel(items.filter(i=>i.supplier===supplier),sums(items.filter(i=>i.supplier===supplier),'supply'))}return shell('admin',content)}
function subCount(items){return new Set(items.map(i=>i.order.id+'-'+i.supplier)).size}
function approve(oid,uid){let[o,i]=findItem(oid,uid);confirmAction('模拟退款',`${esc(i.name)}：${money(i.price*i.qty)}。相关佣金 ${money(o.ref?commission(i):0)} 与供货应付 ${money(supply(i))} 同步冲减。其他商品项继续履约。`,()=>{if(i.refund!=='pending')return;i.refund='approved';i.status='已取消';i.eligible=false;i.refundedAt=Date.now();if(i.commissionSettled)S.settlements.unshift({id:'TKC'+Date.now(),type:'commission',amount:-commission(i),time:Date.now(),note:'售后冲抵 '+i.uid});if(i.supplySettled)S.settlements.unshift({id:'TKS'+Date.now(),type:'supply',supplier:i.supplier,amount:-supply(i),time:Date.now(),note:'售后冲抵 '+i.uid});save();render();toast('模拟退款完成，商品项与金额已同步')})}
function reject(oid,uid){confirmAction('驳回售后','将恢复该商品项的原履约状态并解除冻结。',()=>{let[o,i]=findItem(oid,uid);i.refund=null;save();render();toast('已驳回，冻结已解除')})}
function toggleProduct(id){let p=S.products.find(p=>p.id===id);p.active=!p.active;save();render();toast(p.active?'商品已上架':'商品已下架')}
function editProduct(id){let p=S.products.find(p=>p.id===id),sp=p?.specs[0];modal(`<h2>${p?'编辑商品':'新增商品'}</h2><p class="muted">保存后商城同步，历史订单保留原有价格及佣金快照。</p><label>名称<input id="pn" value="${esc(p?.name||'')}"></label><div class="two"><label>分类<select id="pc">${cats.map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>供应商<select id="ps">${suppliers.map((s,i)=>`<option value="${i}" ${p?.supplier===i?'selected':''}>${s}</option>`).join('')}</select></label></div><label>基础规格<input id="psp" value="${esc(sp?.name||'标准装')}"></label><div class="two"><label>零售价（元）<input id="pp" type="number" min="0.01" step="0.01" value="${sp?sp.price/100:59.9}"></label><label>供货价（元）<input id="pco" type="number" min="0" step="0.01" value="${sp?sp.cost/100:38}"></label></div><label>佣金比例（%）<input id="pr" type="number" min="0" max="100" value="${p?.rate??10}"></label>${p?.specs.length>1?'<p class="muted">此处编辑基础规格，其他规格保留原价。</p>':''}<button class="primary" onclick="saveProduct(${id||0})">保存商品</button>`)}
function saveProduct(id){let name=$('#pn').value.trim(),price=Math.round(Number($('#pp').value)*100),cost=Math.round(Number($('#pco').value)*100),rate=Number($('#pr').value),sp=$('#psp').value.trim();if(!name||!sp||!Number.isFinite(price)||price<=0||!Number.isFinite(cost)||cost<0||!Number.isFinite(rate)||rate<0||rate>100)return toast('请填写有效名称、规格、金额和佣金比例');let p=S.products.find(p=>p.id===id);if(!p){p={id:Math.max(...S.products.map(p=>p.id))+1,image:'apple',origin:'演示产地',desc:'认真甄选，分享日常之好',active:true,specs:[]};S.products.push(p)}Object.assign(p,{name,category:$('#pc').value,supplier:Number($('#ps').value),rate});p.specs[0]={name:sp,price,cost};save();closeModal();render();toast('商品已保存，商城已同步')}
function guide(){modal(`<span class="eyebrow">3 MINUTE WALKTHROUGH</span><h2>从一份分享，到一笔结算。</h2><p class="muted">消费者林悦与推广员陈沐为不同虚构人物。建议先恢复初始数据，核心流程的新增订单会排在最前。</p><ol><li>点击下方「载入购物车」：自动从推广入口关联陈沐，加入苹果与香米，合计 <b>¥129.80</b>。</li><li>消费者「去结算 → 模拟支付」，生成一个主单、两个履约子单。</li><li>切换「推广员 → 推广订单与佣金」，查看预估 <b>¥12.98</b>。</li><li>切换「供应商」，选择「谷仓食集」，对最新香米子单发货。</li><li>切回「消费者 → 我的」，对苹果申请退款；冻结 <b>¥5.99</b> 佣金及 <b>¥38.00</b> 应付。</li><li>「平台管理 → 售后处理」，审批并模拟退款 <b>¥59.90</b>。</li><li>「消费者 → 我的」，确认收到香米。</li><li>点击「模拟满足结算条件」，确认推进等待期。</li><li>「推广员」模拟结算 <b>¥6.99</b>；「供应商 → 谷仓食集 → 应收与结算」模拟结算 <b>¥45.00</b>，查看记录。</li></ol><p class="muted">历史完成样例已结算，不影响本次 ¥6.99 与 ¥45.00 的结算演示。当前浏览器操作会保存，其他浏览器数据独立。</p><button class="primary" onclick="closeModal();loadCart()">开始完整演示 →</button>`)}
function reset(){confirmAction('恢复初始演示数据','将清除当前浏览器的订单、购物车、修改与结算记录，恢复预置虚构样例。',()=>{S=initial();save();role='消费者';tab='';filter='';query='';orderFilter='全部';view='home';render();toast('已恢复初始演示数据')})}
function render(){let html=role==='推广员'?promoter():role==='供应商'?supplierPage():role==='平台管理'?adminPage():({home,list,detail,cart,checkout:checkoutPage,success,orders}[view]||home)();$('#app').innerHTML=html+toolbar()}
let params=new URLSearchParams(location.search);if(params.get('ref')==='HG001'){S.ref='HG001';save()}if(params.has('product')){current=Number(params.get('product'));if(S.products.some(p=>p.id===current))view='detail'}render();

window.addEventListener('storage',e=>{if(e.key==='haowuji-v1'&&e.newValue){try{S=JSON.parse(e.newValue);render()}catch{}}});
